import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import vm from 'node:vm';

const root = import.meta.dirname;
const artifact = '/workspace/scratch/c714f5bce554/ci-current-823/artifact-14473682433';
const hash = bytes => crypto.createHash('sha256').update(bytes).digest('hex');
const files = {
  'opencode-v2-embedded-host.json': 'bd682bbbb2ad463dfcc20a1c2bfd704a633f1db9384b27f4b6ce31a65f4986f8',
  'opencode-v2-embedded-host-auto.json': 'b6202512a9eef253f248a82d9475fbcb5dd4063356578a9b51e5d3d128592055',
  'opencode-v2-embedded-inputs.json': 'f91e4902cc2e8ba6ad629332115039f6b0df4b8a299fed195d6b2be41f2f99f4',
  'opencode-v2-windows-custody.json': '354c1c12164d6dee53488e52ec56893cd85cef54b98afdaa0e2eca53b3219cc0',
};
const exact = new Map();
for (const [name, expected] of Object.entries(files)) {
  const bytes = fs.readFileSync(path.join(artifact, name));
  assert.equal(hash(bytes), expected);
  exact.set(name, bytes.toString('utf8'));
}
const zipName = 'opencode-v2-embedded-native-win32-x64-823.zip';
assert.equal(hash(fs.readFileSync(path.join(artifact, zipName))),
  '4fc52d30bada51617ed2c2eef3a2c2db36d2fece528639ce90511a78aa727613');
const inputs = JSON.parse(exact.get('opencode-v2-embedded-inputs.json'));
const custody = JSON.parse(exact.get('opencode-v2-windows-custody.json'));
assert.equal(inputs.sourceHead, '823ef00a5cd081ccc3efdad85faf41e1cd888a27');
assert.equal(inputs.platform, 'win32-x64');
assert.equal(custody.status, 'PASS');
assert.equal(custody.cleanup, true);
const environment = Object.freeze({
  OPENCODE_V2_EMBEDDED_PRODUCT_ADMITTED: '1',
  OPENCODE_V2_EMBEDDED_HOST_RECEIPT: 'opencode-v2-embedded-host.json',
  OPENCODE_V2_TEST_SOURCE_HEAD: inputs.sourceHead,
  OPENCODE_V2_TEST_PLATFORM: inputs.platform,
  OPENCODE_V2_EMBEDDED_BUN_SHA256: inputs.bun.sha256,
  OPENCODE_V2_EMBEDDED_MANIFEST_SHA256: inputs.manifestSha256,
});
const before = fs.readFileSync(path.join(root, 'before-verifier.mjs'), 'utf8');
const after = fs.readFileSync(path.join(root, 'after-verifier.mjs'), 'utf8');
const marker = 'all_image_MIMEs_exact_PDF_and_4MiB_PNG_native_normalization_and_public_readback';
assert.equal(after.replace("              '" + marker + "',\n", ''), before);
const results = [];

async function check(label, script, change, expectedPass, expectedReads) {
  const selected = new Map(exact);
  if (change) change(selected);
  const reads = [];
  const readPort = Object.freeze({
    readFileSync(name, encoding) {
      assert.ok(name === 'opencode-v2-embedded-host.json' || name === 'opencode-v2-embedded-host-auto.json');
      assert.equal(encoding, 'utf8');
      reads.push(name);
      return selected.get(name);
    },
  });
  const context = vm.createContext({ process: Object.freeze({ platform: 'win32', arch: 'x64', env: environment }) });
  const module = new vm.SourceTextModule(script, { context, identifier: label });
  await module.link(specifier => {
    assert.ok(specifier === 'node:assert/strict' || specifier === 'node:fs');
    const exported = specifier === 'node:assert/strict' ? assert : readPort;
    return new vm.SyntheticModule(['default'], function () { this.setExport('default', exported); }, { context });
  });
  let failure = null;
  try { await module.evaluate({ timeout: 1000 }); }
  catch (error) {
    failure = { name: error.name, code: error.code, operator: error.operator,
      actual: Array.isArray(error.actual) ? [...error.actual] : error.actual,
      expected: Array.isArray(error.expected) ? [...error.expected] : error.expected };
  }
  assert.equal(failure === null, expectedPass, label);
  assert.equal(reads.length, expectedReads, label);
  if (!expectedPass) {
    assert.equal(failure.code, 'ERR_ASSERTION', label);
    assert.equal(failure.operator, 'deepStrictEqual', label);
  }
  results.push({ label, outcome: failure === null ? 'PASS' : 'EXPECTED_REFUSAL', reads, failure });
}

const mutate = (name, fn) => selected => {
  const receipt = JSON.parse(selected.get(name));
  fn(receipt);
  selected.set(name, JSON.stringify(receipt));
};
await check('original-verifier-original-receipts', before, null, false, 1);
await check('one-line-fix-original-manual-and-auto-receipts', after, null, true, 2);
await check('missing-media-proof-refused', after,
  mutate('opencode-v2-embedded-host.json', r => { r.steps.splice(r.steps.indexOf(marker), 1); }), false, 1);
await check('extra-auto-step-refused', after,
  mutate('opencode-v2-embedded-host-auto.json', r => { r.steps.push('TEST-unexpected-step'); }), false, 2);
await check('reordered-auto-media-proof-refused', after,
  mutate('opencode-v2-embedded-host-auto.json', r => {
    const at = r.steps.indexOf(marker); [r.steps[at - 1], r.steps[at]] = [r.steps[at], r.steps[at - 1]];
  }), false, 2);

for (const [name, expected] of Object.entries(files))
  assert.equal(hash(fs.readFileSync(path.join(artifact, name))), expected);
const receipt = {
  schemaVersion: 1,
  kind: 'finite-actual-workflow-verifier-original-receipt-replay',
  checkedAt: new Date().toISOString(),
  nativeReceiptHead: inputs.sourceHead,
  workflowSourceHead: '547e603c555be471394e9c6e4b6a53092a33a6d7',
  runtime: { nodeVersion: process.version, platform: process.platform, arch: process.arch },
  explicitVerifierContext: { platform: 'win32', arch: 'x64', environment },
  contextQualification: 'Offline VM evaluation of exact inline JavaScript body with a two-file read-only receipt port and original Windows branch inputs. No native, Host, app or workflow execution.',
  artifact: { id: 14473682433, zipSha256: '4fc52d30bada51617ed2c2eef3a2c2db36d2fece528639ce90511a78aa727613', files, originalFilesUnchangedBeforeAfter: true },
  scripts: { beforeSha256: hash(before), afterSha256: hash(after), oneLineOnly: true, runnerSha256: hash(fs.readFileSync(import.meta.filename)) },
  summary: { originalRefusalReproduced: 1, fullVerifierPassed: 1, originalReceiptsFullyChecked: 2, exactStepNegativeRefusals: 3 },
  results,
  qualification: 'The historical native jobs and their conclusion are unchanged; this is a finite verifier RED-to-GREEN proof. Fresh current-head original CI remains required. All existing post-roster qualification and Windows-shell assertions ran for both original receipts.',
};
fs.writeFileSync(path.join(root, 'verifier-evidence.json'), JSON.stringify(receipt, null, 2) + '\n');
console.log(JSON.stringify({ ...receipt.summary, result: 'PASS', originalBytesPreserved: true }));
